	b := vBook()
	vPost(b, 6, "Party", Line{Account: "expenses:food", Cents: 800, Tag: "party"}, Line{Account: "assets:cash", Cents: -800})
	if got, _ := b.BalanceTagged("expenses:food", "party"); got != 800 {
		t.Fatalf("got %d", got)
	}
}

