	_, err = b.Post(1, "x", hLn("assets:cash", 5), hLn("income:sales", -4))
	hIs(t, "unbalanced", err, ErrUnbalanced)
	_, err = b.Post(1, "x", hLn("assets:cash", 5), hLn("income:sales", -3), hLn("income:sales", -2), hLn("assets:bank", 0))
