func TestBaseBalancesAndReport(t *testing.T) {
	b := hBook()
	for name, want := range map[string]int64{"assets:bank": 60000, "assets:cash": 23550, "liabilities:loan": -100000, "income:sales": -25000, "expenses:rent": 40000, "expenses:food": 1450} {
