package tallybook

import (
	"errors"
	"fmt"
	"reflect"
	"strings"
	"testing"
)

var _ = strings.ToUpper
var _ = fmt.Sprint
var _ = reflect.DeepEqual
var _ = errors.Is

func hLn(acct string, cents int64) Line { return Line{Account: acct, Cents: cents} }

func hPost(b *Book, day int, memo string, lines ...Line) int {
	id, err := b.Post(day, memo, lines...)
	if err != nil {
		panic(err)
	}
	return id
}

// hBook: a small club ledger. Balances: bank 600.00, cash 235.50, food 14.50, rent 400.00, sales -250.00, loan -1000.00.
func hBook() *Book {
	b := New()
	for _, a := range []struct {
		name string
		kind Kind
	}{{"assets:cash", Asset}, {"assets:bank", Asset}, {"liabilities:loan", Liability}, {"income:sales", Income}, {"expenses:rent", Expense}, {"expenses:food", Expense}} {
		if err := b.Open(a.name, a.kind); err != nil {
			panic(err)
		}
	}
	hPost(b, 1, "Opening loan", hLn("assets:bank", 100000), hLn("liabilities:loan", -100000))
	hPost(b, 2, "Sale", hLn("assets:cash", 25000), hLn("income:sales", -25000))
	hPost(b, 3, "Rent", hLn("expenses:rent", 40000), hLn("assets:bank", -40000))
	hPost(b, 5, "Groceries", hLn("expenses:food", 1450), hLn("assets:cash", -1450))
	return b
}

func hIDs(es []Entry) []int {
	out := []int{}
	for _, e := range es {
		out = append(out, e.ID)
	}
	return out
}

func hEq(t *testing.T, name string, got, want interface{}) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		t.Errorf("%s: got %v, want %v", name, got, want)
	}
}

func hIs(t *testing.T, name string, err, target error) {
	t.Helper()
	if !errors.Is(err, target) {
		t.Errorf("%s: got %v, want %v", name, err, target)
	}
}

func TestBaseOpen(t *testing.T) {
	b := New()
	for _, bad := range []string{"", "  ", "Cash", "assets:", ":x", "a b", "1abc", "assets::cash", "a_b", "assets:Cash"} {
