	b.OpenIn("equity:fx-other", Liability, "CHF")
	hPost(b, 6, "Gift", hLn("assets:other", 1234), hLn("equity:fx-other", -1234))
	hEq(t, "report", b.Report(), "assets:bank              GBP     600.00\nassets:cash              GBP     235.50\nassets:other             CHF      12.34\nequity:fx-other          CHF     -12.34\nexpenses:food            GBP      14.50\nexpenses:rent            GBP     400.00\nincome:sales             GBP    -250.00\nliabilities:loan         GBP   -1000.00\n")
}

