package tallybook

import (
	"errors"
	"fmt"
	"reflect"
	"strings"
	"testing"
)

var _ = strings.ToUpper
var _ = fmt.Sprint
var _ = reflect.DeepEqual
var _ = errors.Is

func vLn(acct string, cents int64) Line { return Line{Account: acct, Cents: cents} }

func vPost(b *Book, day int, memo string, lines ...Line) int {
	id, err := b.Post(day, memo, lines...)
	if err != nil {
		panic(err)
	}
	return id
}

// vBook: a small club ledger. Balances: bank 600.00, cash 235.50, food 14.50, rent 400.00, sales -250.00, loan -1000.00.
func vBook() *Book {
	b := New()
	for _, a := range []struct {
		name string
		kind Kind
	}{{"assets:cash", Asset}, {"assets:bank", Asset}, {"liabilities:loan", Liability}, {"income:sales", Income}, {"expenses:rent", Expense}, {"expenses:food", Expense}} {
		if err := b.Open(a.name, a.kind); err != nil {
			panic(err)
		}
	}
	vPost(b, 1, "Opening loan", vLn("assets:bank", 100000), vLn("liabilities:loan", -100000))
	vPost(b, 2, "Sale", vLn("assets:cash", 25000), vLn("income:sales", -25000))
	vPost(b, 3, "Rent", vLn("expenses:rent", 40000), vLn("assets:bank", -40000))
	vPost(b, 5, "Groceries", vLn("expenses:food", 1450), vLn("assets:cash", -1450))
	return b
}

func vIDs(es []Entry) []int {
	out := []int{}
	for _, e := range es {
		out = append(out, e.ID)
	}
	return out
}

func TestOpenAndPost(t *testing.T) {
	b := vBook()
	if err := b.Open("assets:cash", Asset); !errors.Is(err, ErrDuplicate) {
		t.Fatalf("duplicate: %v", err)
	}
	if err := b.Open("Cash", Asset); !errors.Is(err, ErrBadName) {
		t.Fatalf("bad name: %v", err)
	}
	if _, err := b.Post(1, "x", vLn("assets:cash", 5)); !errors.Is(err, ErrTooFew) {
		t.Fatalf("one line: %v", err)
	}
	if _, err := b.Post(1, "x", vLn("assets:cash", 5), vLn("income:sales", -4)); !errors.Is(err, ErrUnbalanced) {
		t.Fatalf("unbalanced: %v", err)
	}
	if id := vPost(b, 6, "  Tea  ", vLn("expenses:food", 300), vLn("assets:cash", -300)); id != 5 {
