// vBook: a small club ledger. Balances: bank 600.00, cash 235.50, food 14.50, rent 400.00, sales -250.00, loan -1000.00.
func vBook() *Book {
	b := New()
	for _, a := range []struct {
		name string
		kind Kind
	}{{"assets:cash", Asset}, {"assets:bank", Asset}, {"liabilities:loan", Liability}, {"income:sales", Income}, {"expenses:rent", Expense}, {"expenses:food", Expense}} {
		if err := b.Open(a.name, a.kind); err != nil {
			panic(err)
		}
	}
	vPost(b, 1, "Opening loan", vLn("assets:bank", 100000), vLn("liabilities:loan", -100000))
	vPost(b, 2, "Sale", vLn("assets:cash", 25000), vLn("income:sales", -25000))
	vPost(b, 3, "Rent", vLn("expenses:rent", 40000), vLn("assets:bank", -40000))
	vPost(b, 5, "Groceries", vLn("expenses:food", 1450), vLn("assets:cash", -1450))
