	if got, _ := b.BalanceAt("assets:bank", 2); got != 100500 {
		t.Errorf("late entry counts by its day: %d", got)
	}
	if got, _ := b.BalanceAt("assets:bank", 1); got != 100000 {
		t.Errorf("but not before it: %d", got)
