}

func TestBalanceAtErrors(t *testing.T) {
	b := hBook()
	_, err := b.BalanceAt("nope", -5)
	hIs(t, "unknown first", err, ErrUnknownAccount)
	_, err = b.BalanceAt("assets:bank", -1)
