	}
}

func TestJournalPostErrorsAreAllOrNothing(t *testing.T) {
	b := hBook()
	text := "10 fine\n  assets:cash 1\n  income:sales -1\n\n11 unknown\n  assets:cash 1\n  nope -1\n"
